/*
 *  KONGQUE-LIGHT // the Peacock Room's gold, relit (after components/gold-ground and lustre-stars).
 *
 *  Markup:  <figure class="kl" data-kongque-light data-origin=".47 .52">
 *             <img src="assets/room/mural-1400.webp" data-full="assets/room/mural.webp" alt="…">
 *           </figure>
 *  The light data sits beside each image as <name>-gold.png (tools/gold_bake.py). Or call
 *  goldLight(figure, { gold, origin, distance, light }) yourself; it returns destroy(), which
 *  also carries zoom(z) (the magnification, eased; the img follows through the --z property),
 *  aim(x, y) (hold the light at a point in the figure, 0..1; aim() lets go) and advance(s).
 *  data-sharp (default 1) tightens and heats the flash; data-deep (.28) is how far gold not catching sits below the
 *  photograph; data-rest ".3 .22" is where the lamp stands with no pointer (and under reduced motion); data-sweep
 *  carries a lamp once across the figure, slowly, the first time it comes into view.
 *
 *  Whistler painted the room in Prussian blue and gold: gold leaf on the shutters, the shelves
 *  and the ceiling's ribs, gold paint for the peacocks of the mural. The photograph is the colour.
 *  Offline each photograph was given a gold mask (from its colour) and a normal (the paint's rim
 *  where it stands proud of the ground, its brushwork and the leaf's surface from the photograph's
 *  own fine detail, and a slow wander of a degree or two, as leaf never lies flat), packed in one
 *  lossless PNG:
 *
 *    R, G  the normal's x and y (128 = straight out, +-127 = +-0.5)
 *    B     gold (0 = the ground, lacquer, porcelain; 255 = gold)
 *
 *  A lamp is carried by the pointer (or held up and to the left of the wall; the phone's tilt
 *  turns the wall under it) and the eye is at the middle of the screen, so scrolling moves the
 *  eye. Gold reflects the lamp as a warm lobe in its own colour, near white at the peak, and gold
 *  not catching it sits a little deeper than the photograph's flash. The blue ground stays matte,
 *  with a faint broad sheen. Nothing is recoloured: away from the light the picture is the photograph.
 *
 *  Draws only while something moves (pointer, scroll, tilt, the lamp easing, the zoom easing) and
 *  only on screen: zero frames idle. Reduced motion: one still frame, the lamp fixed. Without JS or
 *  WebGL, or if the data fails: the photograph.
 */
const calm = matchMedia('(prefers-reduced-motion: reduce)');
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const TILT_TURN = 0.3;

const VERT = `
attribute vec2 p;
varying vec2 vUv;
void main() { vUv = vec2(p.x * .5 + .5, .5 - p.y * .5); gl_Position = vec4(p, 0., 1.); }`;

const FRAG = `
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uAlb;      // the photograph
uniform sampler2D uData;     // normal xy, gold
uniform vec2 uSize;          // the figure, css px
uniform float uZoom;         // the magnification, about uOrigin (as the img's CSS transform)
uniform vec2 uOrigin;
uniform vec3 uEye;           // css px from the figure's top left; z out of the wall
uniform vec3 uLamp;
uniform vec2 uTiltN;
uniform float uK;            // the lamp's strength
uniform float uSharp;        // 1 = the room's general gold; above 1, a tighter, hotter flash (leaf that blazes)
uniform float uDeep;         // how far gold not catching sits below the photograph (0..1)
varying vec2 vUv;

float lobe(float nh, float w2) { return exp(-(1. - nh) * 2. / w2); }

void main() {
    vec2 uv = uOrigin + (vUv - uOrigin) / uZoom;
    vec3 alb = texture2D(uAlb, uv).rgb;
    vec3 d = texture2D(uData, uv).rgb;
    float g = d.b;
    vec2 t = (d.rg * 255. - 128.) / 127. * .5 * sqrt(uZoom);   // magnified, the relief reads a little stronger
    vec3 P = vec3(vUv * uSize, 0.);
    vec3 N = normalize(vec3(t + uTiltN, 1.));
    vec3 V = normalize(uEye - P);
    vec3 L = normalize(uLamp - P);
    vec3 H = normalize(L + V);
    float nh = max(dot(N, H), 0.);
    float nl = max(dot(N, L), 0.);

    // gold: the lamp thrown back in the gold's own colour (leaf and paint are warm, brassier where
    // the photograph is greener), a tight flash and a broader glow; near white at the peak
    float lum = max(dot(alb, vec3(.3, .55, .15)), .05);
    vec3 own = alb / lum;
    vec3 metal = mix(vec3(1., .8, .5), own * vec3(1.05, .86, .6), .45);
    float l1 = lobe(nh, .006 / uSharp);
    float l2 = lobe(nh, .045 / sqrt(uSharp));
    vec3 spec = metal * (l1 * 1.25 * uSharp + l2 * .5);
    // gold not catching the lamp sits deeper than the flash-lit photograph: leaf is dark off the mirror angle
    vec3 goldC = alb * (1. - uDeep + .14 * nl) + spec * uK;
    // the ground: matte paint on leather, a faint broad sheen and nothing more
    vec3 groundC = alb + vec3(.85, .92, 1.) * lobe(nh, .09) * .03 * uK;
    vec3 c = mix(groundC, goldC, g);
    vec3 hi = max(c - .8, 0.);
    c = min(c, .8) + .2 * (1. - exp(-hi / .2));
    gl_FragColor = vec4(c, 1.);
}`;

export function goldLight(root, opts = {}) {
    const img = root && root.querySelector('img');
    if (!img) return () => {};
    const ds = root.dataset;
    const num = (v, d) => { const n = parseFloat(v); return Number.isFinite(n) ? n : d; };
    const org = String(opts.origin ?? ds.origin ?? '.5 .5').split(/[\s,]+/).map(Number);
    const cfg = {
        gold: opts.gold ?? ds.gold,
        origin: [num(org[0], .5), num(org[1], .5)],
        distance: Math.max(.6, num(opts.distance ?? ds.distance, 1.4)),
        light: clamp(num(opts.light ?? ds.light, 1), 0, 2),
        sharp: clamp(num(opts.sharp ?? ds.sharp, 1), .5, 4),
        deep: clamp(num(opts.deep ?? ds.deep, .28), 0, .7),
        sweep: (opts.sweep ?? ds.sweep) != null && (opts.sweep ?? ds.sweep) !== false && (opts.sweep ?? ds.sweep) !== 'false',
        rest: String(opts.rest ?? ds.rest ?? '.3 .22').split(/[\s,]+/).map(Number),
    };
    let dead = false, gl = null, gl2 = false, canvas = null, prog = null, quad = null, texAlb = null, texData = null;
    let W = 0, H = 0, cw = 0, ch = 0, visible = false, raf = 0, last = 0, lastKey = '', srcKey = '';
    const off = [];
    const on = (t, e, f, o) => { t.addEventListener(e, f, o); off.push(() => t.removeEventListener(e, f, o)); };

    const zoom = { x: 1, v: 0, to: 1 };
    const REST = [num(cfg.rest[0], .3), num(cfg.rest[1], .22)];
    const lamp = { x: REST[0], y: REST[1], tx: REST[0], ty: REST[1] };      // in figure units
    // data-sweep: the first time the figure comes into view, a lamp is carried once slowly across it
    let sweep = null;               // { t0 } while it runs
    const SWEEP_S = 3.2;
    let pointer = null, held = null;
    let tilt = { x: 0, y: 0, active: false };
    const tiltN = { x: 0, y: 0 };

    function initGL() {
        const o = { alpha: false, antialias: false, depth: false, stencil: false, preserveDrawingBuffer: false };
        gl = canvas.getContext('webgl2', o);
        gl2 = !!gl;
        if (!gl) gl = canvas.getContext('webgl', o);
        if (!gl) return false;
        const sh = (type, src) => {
            const s = gl.createShader(type);
            gl.shaderSource(s, src); gl.compileShader(s);
            if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) { console.warn(gl.getShaderInfoLog(s)); return null; }
            return s;
        };
        const vs = sh(gl.VERTEX_SHADER, VERT), fs = sh(gl.FRAGMENT_SHADER, FRAG);
        if (!vs || !fs) return false;
        prog = gl.createProgram();
        gl.attachShader(prog, vs); gl.attachShader(prog, fs);
        gl.bindAttribLocation(prog, 0, 'p');
        gl.linkProgram(prog);
        if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return false;
        prog.u = {};
        for (const n of ['uAlb', 'uData', 'uSize', 'uZoom', 'uOrigin', 'uEye', 'uLamp', 'uTiltN', 'uK', 'uSharp', 'uDeep']) prog.u[n] = gl.getUniformLocation(prog, n);
        quad = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, quad);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
        gl.enableVertexAttribArray(0);
        gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
        texAlb = gl.createTexture(); texData = gl.createTexture();
        return true;
    }
    // upload an image; with WebGL2, mipmapped, so a large photograph shown small stays calm
    function upload(t, im, data) {
        gl.bindTexture(gl.TEXTURE_2D, t);
        gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
        gl.pixelStorei(gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, data ? gl.NONE : gl.BROWSER_DEFAULT_WEBGL);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, im);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        if (gl2) { gl.generateMipmap(gl.TEXTURE_2D); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR); }
        else gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    }
    const loadImage = (src) => new Promise((res, rej) => { const i = new Image(); i.decoding = 'async'; i.onload = () => res(i); i.onerror = rej; i.src = src; });
    const goldFor = (src) => cfg.gold && !img.dataset.full ? cfg.gold : src.replace(/\.[a-z0-9]+(\?.*)?$/i, '-gold.png');

    // the photograph and its data, for whichever image the <img> shows now (the small one, then the full one)
    async function textures() {
        const src = img.currentSrc || img.src;
        if (src === srcKey) return;
        try { await img.decode(); } catch (e) { /* drawn when it loads */ }
        if (dead || !img.naturalWidth) return;
        const max = gl.getParameter(gl.MAX_TEXTURE_SIZE);
        if (img.naturalWidth > max || img.naturalHeight > max) throw new Error('too large');
        const data = await loadImage(new URL(goldFor(src), document.baseURI).href);
        if (dead || (img.currentSrc || img.src) !== src) return;
        upload(texAlb, img, false);
        upload(texData, data, true);
        srcKey = src; lastKey = '';
        root.classList.add('kl-live');
        if (calm.matches) still(); else kick();
    }

    function layout() {
        const r = root.getBoundingClientRect();
        W = Math.max(1, r.width); H = Math.max(1, r.height);
        const dpr = Math.min(devicePixelRatio || 1, 2);
        cw = canvas.width = Math.max(1, Math.round(W * dpr));
        ch = canvas.height = Math.max(1, Math.round(H * dpr));
        lastKey = '';
    }

    function geometry() {
        const r = root.getBoundingClientRect();
        const D = cfg.distance * Math.max(innerWidth, W);
        // the eye at the middle of the screen (so the light slides as the page scrolls past)
        const ex = innerWidth / 2 - r.left, ey = innerHeight / 2 - r.top;
        // the lamp is held near the wall, a third of the way out: its pool falls near it
        return { D, ex, ey, lx: lamp.x * W, ly: lamp.y * H, lz: D * .32 };
    }
    function draw() {
        if (!gl || !srcKey) return;
        const g = geometry();
        gl.viewport(0, 0, cw, ch);
        gl.useProgram(prog);
        const u = prog.u;
        gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, texAlb); gl.uniform1i(u.uAlb, 0);
        gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D, texData); gl.uniform1i(u.uData, 1);
        gl.uniform2f(u.uSize, W, H);
        gl.uniform1f(u.uZoom, zoom.x);
        gl.uniform2f(u.uOrigin, cfg.origin[0], cfg.origin[1]);
        gl.uniform3f(u.uEye, g.ex, g.ey, g.D);
        gl.uniform3f(u.uLamp, g.lx, g.ly, g.lz);
        gl.uniform2f(u.uTiltN, tiltN.x, tiltN.y);
        gl.uniform1f(u.uK, cfg.light);
        gl.uniform1f(u.uSharp, cfg.sharp);
        gl.uniform1f(u.uDeep, cfg.deep);
        gl.bindBuffer(gl.ARRAY_BUFFER, quad);
        gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    }

    // ── motion: the lamp eases to the pointer; the zoom on a critically damped spring ──
    const STEP = 1 / 120, WZ = 2 * Math.PI / .7;
    let acc = 0;
    function sweepAt(t) {
        // left to right, a little above the middle, easing in and out; a gentle rise and fall
        const f = clamp((t - sweep.t0) / 1000 / SWEEP_S, 0, 1), e = f * f * (3 - 2 * f);
        return [-.08 + 1.16 * e, .42 - .12 * Math.sin(Math.PI * e)];
    }
    function target(t) {
        if (held) return held;
        if (sweep) {
            if (!pointer && (t ?? performance.now()) - sweep.t0 < SWEEP_S * 1000) return sweepAt(t ?? performance.now());
            sweep = null;
        }
        if (pointer) {
            const r = root.getBoundingClientRect();
            return [(pointer.x - r.left) / W, (pointer.y - r.top) / H];
        }
        return REST;
    }
    function setZoomStyle() { root.style.setProperty('--z', zoom.x.toFixed(4)); }
    function frame(t) {
        raf = 0;
        if (dead || !gl || gl.isContextLost()) { last = 0; return; }
        const dt = last ? Math.min(.05, (t - last) / 1000) : 1 / 60;
        last = t;
        const [tx, ty] = target(t);
        lamp.tx = tx; lamp.ty = ty;
        const k = 1 - Math.exp(-dt / .12);
        lamp.x += (tx - lamp.x) * k; lamp.y += (ty - lamp.y) * k;
        acc += dt;
        while (acc >= STEP) { zoom.v += (-WZ * WZ * (zoom.x - zoom.to) - 2 * WZ * zoom.v) * STEP; zoom.x += zoom.v * STEP; acc -= STEP; }
        if (tilt.active) {
            const kt = 1 - Math.exp(-dt / .12);
            tiltN.x += (tilt.x * TILT_TURN - tiltN.x) * kt; tiltN.y += (tilt.y * TILT_TURN - tiltN.y) * kt;
        }
        const zMoving = Math.abs(zoom.x - zoom.to) > 2e-4 || Math.abs(zoom.v) > 2e-3;
        if (!zMoving) { zoom.x = zoom.to; zoom.v = 0; }
        setZoomStyle();
        const moving = zMoving || !!sweep || Math.abs(lamp.x - tx) + Math.abs(lamp.y - ty) > 5e-4
            || (tilt.active && Math.abs(tilt.x * TILT_TURN - tiltN.x) + Math.abs(tilt.y * TILT_TURN - tiltN.y) > 5e-4);
        const r = root.getBoundingClientRect();
        const key = [zoom.x * 1e3, lamp.x * 1e3, lamp.y * 1e3, r.left, r.top, W, H, tiltN.x * 1e3, tiltN.y * 1e3].map((x) => x.toFixed(1)).join();
        if (visible && key !== lastKey) { draw(); lastKey = key; }
        if (moving && visible && !document.hidden) raf = requestAnimationFrame(frame);
        else { last = 0; acc = 0; if (!moving) return; }
    }
    function kick() {
        if (dead) return;
        if (calm.matches) { still(); return; }
        if (!raf && gl) raf = requestAnimationFrame(frame);
    }
    // reduced motion: the zoom lands at once, the lamp stands still, one frame
    function still() {
        zoom.x = zoom.to; zoom.v = 0; setZoomStyle();
        const [tx, ty] = held || REST;
        lamp.x = lamp.tx = tx; lamp.y = lamp.ty = ty;
        tiltN.x = tiltN.y = 0;
        if (gl && visible) draw();
    }

    let io = null, ro = null, swept = false;
    async function start() {
        canvas = document.createElement('canvas');
        canvas.className = 'kl-canvas';
        canvas.setAttribute('aria-hidden', 'true');
        try { if (!initGL()) throw new Error('no webgl'); } catch (e) { canvas = null; gl = null; return; }
        root.appendChild(canvas);
        layout();
        try { await textures(); } catch (e) { canvas.remove(); canvas = null; gl = null; root.classList.remove('kl-live'); return; }
        on(img, 'load', () => { textures().catch(() => {}); });
        on(canvas, 'webglcontextlost', (e) => { e.preventDefault(); cancelAnimationFrame(raf); raf = 0; root.classList.remove('kl-live'); });
        on(canvas, 'webglcontextrestored', () => { if (initGL()) { srcKey = ''; textures().catch(() => {}); } });
        on(window, 'pointermove', (e) => {
            if (e.pointerType === 'touch' || calm.matches) return;
            pointer = { x: e.clientX, y: e.clientY }; if (visible) kick();
        }, { passive: true });
        on(document.documentElement, 'pointerleave', () => { pointer = null; kick(); });
        on(window, 'scroll', () => { if (visible && !calm.matches) kick(); }, { passive: true });
        on(window, 'deviceorientation', () => { if (tilt.active && visible && !calm.matches) kick(); }, { passive: true });
        on(document, 'visibilitychange', () => { if (!document.hidden) { last = 0; kick(); } });
        on(calm, 'change', () => { lastKey = ''; calm.matches ? still() : kick(); });
        import('./tilt.js').then((m) => { tilt = m.default; }).catch(() => {});
        io = new IntersectionObserver((en) => {
            visible = en[0].isIntersecting;
            if (!visible) return;
            lastKey = '';
            // the first time it is well in view, carry a lamp across it once, so the gold is seen to be gold
            if (cfg.sweep && !swept && !calm.matches && en[0].intersectionRatio > .45) { swept = true; sweep = { t0: performance.now() }; lamp.x = -.08; lamp.y = .42; }
            calm.matches ? still() : kick();
        }, { rootMargin: '0px', threshold: [0, .45] });
        io.observe(root);
        ro = new ResizeObserver(() => { if (!gl) return; layout(); calm.matches ? still() : kick(); });
        ro.observe(root);
    }
    start();

    const api = function destroy() {
        dead = true;
        cancelAnimationFrame(raf);
        off.forEach((f) => f());
        if (io) io.disconnect();
        if (ro) ro.disconnect();
        if (gl) { const x = gl.getExtension('WEBGL_lose_context'); if (x) x.loseContext(); }
        if (canvas) canvas.remove();
        root.classList.remove('kl-live');
        root.style.removeProperty('--z');
    };
    api.zoom = (z) => { zoom.to = Math.max(1, Number(z) || 1); if (!gl) { zoom.x = zoom.to; setZoomStyle(); } else kick(); };
    api.aim = (x, y) => { held = x == null ? null : [x, y]; kick(); };
    api.advance = (s) => {
        for (let i = 0, n = Math.round(s * 120); i < n; i++) {
            zoom.v += (-WZ * WZ * (zoom.x - zoom.to) - 2 * WZ * zoom.v) * STEP; zoom.x += zoom.v * STEP;
            const [tx, ty] = target(); const k = 1 - Math.exp(-STEP / .12);
            lamp.x += (tx - lamp.x) * k; lamp.y += (ty - lamp.y) * k;
        }
        setZoomStyle(); if (gl) draw();
    };
    root.goldLight = api;
    return api;
}

document.querySelectorAll('[data-kongque-light]').forEach((el) => goldLight(el));

// kongque: a range input that is a brisé fan with a peacock at its heart: Kunstnerviften, the Artists' Fan
// (Kristiania, 1898, Nasjonalmuseet NG.M.04483). Eighteen wooden sticks, each painted by a different Norwegian
// artist, opening to a half circle; across the gorge a peacock spreads its tail over all of them.
//
// The control is a real <input type="range"> inside the component, with its <label> and an <output>. The fan is its
// picture: closed is the minimum, fully open the maximum, and every value between opens it that far. Take the top
// guard (or anywhere on the fan) and turn it round the pin, use the keys, or set the value: the fan follows.
//
// Each stick, heel and all, is its own photographed piece (tools/), turning about the rivet in its real stacking
// order, so closing only ever hides photographed pixels; the peacock's tail folds away into the stack as it would.
// The rivet's head and its brass bail do not turn. The sticks open one after another, each settling on its share of
// the opening with a small critically damped spring (the runtime is badbezan's). Fully open and at rest, what you see
// is the <img>: the photograph itself.
//
//   import { kongque } from './kongque.js';
//   const f = kongque(root);  f.value = 120;  f.hold(true); f.advance(.2);  f();  // destroy

const calm = matchMedia('(prefers-reduced-motion: reduce)');
const live = new WeakMap();
const D2R = Math.PI / 180;
// the box the fan needs while it closes, in the photograph's output px (assets/fan.json `box`, rounded out):
// the closed fan reaches 8 px left of the photograph and 16 px below it. The CSS uses the same numbers.
const BOX_X = -8, BOX_W = 2603, BOX_H = 1422;

const loadImage = (src) => new Promise((res, rej) => {
  const i = new Image();
  i.decoding = 'async';
  i.onload = () => (i.decode ? i.decode().catch(() => {}) : Promise.resolve()).then(() => res(i));
  i.onerror = rej;
  i.src = src;
});
const num = (v, d) => { const n = parseFloat(v); return Number.isFinite(n) ? n : d; };
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));

// a region of the atlas, resampled once to `f` (device px per output px), its origin at a sub-pixel offset so
// that, drawn at whole pixels, it lands exactly where the photograph has it. Big reductions go by halves.
function resample(src, sx, sy, sw, sh, f, ox, oy) {
  let cur = src, cx = sx, cy = sy, cw = sw, ch = sh, k = f;
  while (k < .5) {
    const c = document.createElement('canvas');
    c.width = Math.ceil(cw / 2) + 1; c.height = Math.ceil(ch / 2) + 1;
    const g = c.getContext('2d');
    g.imageSmoothingQuality = 'high';
    g.drawImage(cur, cx, cy, cw, ch, 0, 0, cw / 2, ch / 2);
    cur = c; cx = 0; cy = 0; cw /= 2; ch /= 2; k *= 2;
  }
  const out = document.createElement('canvas');
  out.width = Math.ceil(cw * k + ox) + 1; out.height = Math.ceil(ch * k + oy) + 1;
  const g = out.getContext('2d');
  g.imageSmoothingQuality = 'high';
  g.drawImage(cur, cx, cy, cw, ch, ox, oy, cw * k, ch * k);
  return out;
}

export function kongque(root, opts = {}) {
  if (live.has(root)) return live.get(root);
  const ds = root.dataset;
  const o = {
    src: opts.src ?? ds.src,
    format: opts.format ?? ds.format ?? '{value}',      // what the <output> says; {value} is the input's value
    open: num(opts.open ?? ds.open, 13),                 // how briskly the guard follows a value (rad/s)
  };
  const fanEl = root.querySelector('.kq-fan');
  const img = root.querySelector('.kq-img');
  const input = root.querySelector('input[type="range"]');
  const out = root.querySelector('output');
  if (!fanEl || !img || !input) return Object.assign(() => {}, { value: null });

  const offs = [];
  const on = (t, e, f, p) => { t.addEventListener(e, f, p); offs.push(() => t.removeEventListener(e, f, p)); };
  const added = [];

  // ---- state -----------------------------------------------------------------------------------------------------
  let G = null, ready = false, alive = true;
  let a = [], gap = [], N = 0;      // each stick's angle in the photograph (rad, image coords), and the gaps
  let phi = [], om = [];            // each stick's angle now, and its angular speed
  let guardTarget = 0;              // where the top guard is going
  let hand = null;                  // {pid}
  let raf = 0, lastT = 0, visible = true, held = false;
  let canvas, ctx, sprites = [], rivet = null, f = 1, cssW = 0, dpr = 1, P = [0, 0];

  root.classList.add('kq-on');

  const range = () => {
    const min = num(input.min, 0), max = num(input.max, 100);
    return [min, max > min ? max : min + 1, input.step === 'any' ? 0 : num(input.step, 1)];
  };
  const openness = () => { const [min, max] = range(); return clamp((num(input.value, min) - min) / (max - min), 0, 1); };
  const guardFor = (v) => a[0] + v * (a[N - 1] - a[0]);

  function say() {
    if (out) out.textContent = o.format.replace('{value}', input.value);
  }

  // ---- motion ----------------------------------------------------------------------------------------------------
  // each inner stick settles on its share of the guard's opening; the top ones are a little quicker, so a fast
  // flick deals them out from the top. The ribbon is the hard limit: no stick lies further from the one below than
  // it does in the photograph (fully open), and none passes the one below it.
  function stickTarget(k) {
    const v = (phi[N - 1] - a[0]) / (a[N - 1] - a[0]);
    return a[0] + v * (a[k] - a[0]);
  }
  function constrain() {
    for (let it = 0; it < 3; it++) {
      for (let k = N - 2; k >= 1; k--) {
        const lo = phi[k + 1] - gap[k + 1], hi = phi[k + 1];
        if (phi[k] < lo) { phi[k] = lo; om[k] = Math.max(om[k], om[k + 1]); }
        else if (phi[k] > hi) { phi[k] = hi; om[k] = Math.min(om[k], om[k + 1]); }
      }
      for (let k = 1; k < N - 1; k++) {
        const lo = phi[k - 1], hi = phi[k - 1] + gap[k];
        if (phi[k] < lo) { phi[k] = lo; om[k] = Math.max(om[k], om[k - 1]); }
        else if (phi[k] > hi) { phi[k] = hi; om[k] = Math.min(om[k], om[k - 1]); }
      }
    }
  }
  function settle() {               // put everything where it comes to rest
    phi[N - 1] = guardTarget; om[N - 1] = 0;
    for (let k = 1; k < N - 1; k++) { phi[k] = stickTarget(k); om[k] = 0; }
  }
  function step(dt) {
    if (calm.matches && !hand) { settle(); return; }
    const W = hand ? 38 : o.open;
    om[N - 1] += (W * W * (guardTarget - phi[N - 1]) - 2 * W * om[N - 1]) * dt;
    phi[N - 1] += om[N - 1] * dt;
    phi[N - 1] = clamp(phi[N - 1], a[0], a[N - 1]);
    if (calm.matches) { for (let k = 1; k < N - 1; k++) { phi[k] = stickTarget(k); om[k] = 0; } return; }
    for (let k = 1; k < N - 1; k++) {
      const w = 7 + 8 * k / (N - 2);
      om[k] += (w * w * (stickTarget(k) - phi[k]) - 2 * w * om[k]) * dt;
      phi[k] += om[k] * dt;
    }
    constrain();
  }
  function settled() {
    if (hand) return false;
    if (Math.abs(phi[N - 1] - guardTarget) > 2e-5 || Math.abs(om[N - 1]) > 1e-3) return false;
    for (let k = 1; k < N - 1; k++) if (Math.abs(phi[k] - stickTarget(k)) > 2e-5 || Math.abs(om[k]) > 1e-3) return false;
    settle();
    return true;
  }

  // ---- drawing ---------------------------------------------------------------------------------------------------
  function layout() {
    const w = fanEl.clientWidth;
    if (!w || !G) return;
    const d = Math.min(2, devicePixelRatio || 1);
    if (w === cssW && d === dpr && sprites.length) return;
    cssW = w; dpr = d;
    const W = Math.round(w * d), H = Math.round(W * BOX_H / BOX_W);
    f = W / BOX_W;
    canvas.width = W; canvas.height = H;
    P = [(G.pivot[0] - BOX_X) * f, G.pivot[1] * f];
    const make = (s) => {
      const X = (s.x - BOX_X) * f, Y = s.y * f;
      return { cv: resample(G.atlas, s.ax, s.ay, s.w, s.h, f, X - Math.floor(X), Y - Math.floor(Y)), x: Math.floor(X), y: Math.floor(Y) };
    };
    sprites = G.sticks.map(make);
    rivet = make(G.rivet);
    draw();
  }
  function atRest() {
    if (hand) return false;
    for (let k = 1; k < N; k++) if (Math.abs(phi[k] - a[k]) > 1e-6 || om[k] !== 0) return false;
    return true;
  }
  function draw() {
    if (!ready || !sprites.length) return;
    const rest = atRest();
    root.classList.toggle('kq-moving', !rest);
    if (rest) return;                               // fully open and still: the <img> is the photograph
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.imageSmoothingQuality = 'high';
    for (let k = 0; k < N; k++) {
      const s = sprites[k], t = phi[k] - a[k];
      if (Math.abs(t) < 1e-6) ctx.setTransform(1, 0, 0, 1, 0, 0);
      else {
        const c = Math.cos(t), si = Math.sin(t);
        ctx.setTransform(c, si, -si, c, P[0] - c * P[0] + si * P[1], P[1] - si * P[0] - c * P[1]);
      }
      ctx.drawImage(s.cv, s.x, s.y);
    }
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.drawImage(rivet.cv, rivet.x, rivet.y);       // the rivet's head and its bail do not turn
  }

  function frame(t) {
    raf = 0;
    const dt = Math.min(.05, lastT ? (t - lastT) / 1000 : 1 / 60);
    lastT = t;
    for (let k = 0, n = Math.max(1, Math.round(dt * 240)); k < n; k++) step(dt / n);
    const done = settled();
    draw();
    if (!done && visible && !held && !document.hidden) raf = requestAnimationFrame(frame);
    else lastT = 0;
  }
  function wake() {
    if (!ready || held) return;
    if (!visible || document.hidden) { settle(); draw(); return; }
    if (!raf) { lastT = 0; raf = requestAnimationFrame(frame); }
  }

  // ---- the value -------------------------------------------------------------------------------------------------
  function fromInput() {
    say();
    if (!ready) return;
    if (!hand) guardTarget = guardFor(openness());
    root.dispatchEvent(new CustomEvent('kongque:change', { detail: { value: num(input.value, 0), open: openness() } }));
    wake();
  }
  function setValue(v, fire = true) {
    const before = input.value;
    input.value = String(v);
    if (fire && input.value !== before) input.dispatchEvent(new Event('input', { bubbles: true }));
    else fromInput();
  }

  // ---- the hand: take the guard (or anywhere on the fan) round the pin --------------------------------------------
  function pointerAngle(e) {
    const r = fanEl.getBoundingClientRect();
    const k = BOX_W / r.width;
    const x = (e.clientX - r.left) * k + BOX_X - G.pivot[0];
    const y = (e.clientY - r.top) * k - G.pivot[1];
    let t = Math.atan2(y, x);                       // image coords: the fan spans its sticks' angles (fan.json)
    if (t < 0) t += 2 * Math.PI;
    else t = t < Math.PI / 2 ? 2 * Math.PI : Math.PI;   // below the pin: fully open to the right, closed to the left
    return clamp(t, a[0], a[N - 1]);
  }
  function handTo(e) {
    const t = pointerAngle(e);
    guardTarget = t;
    const [min, max, st] = range();
    let v = min + (t - a[0]) / (a[N - 1] - a[0]) * (max - min);
    if (st) v = min + Math.round((v - min) / st) * st;
    v = clamp(v, min, max);
    if (String(v) !== input.value && num(input.value) !== v) setValue(+v.toFixed(6));
    wake();
  }
  // A touch that turns out to be a scroll (the fan lets vertical swipes scroll the page) changes nothing: a finger
  // acts once it moves sideways or lifts as a tap, and a cancelled touch puts the value back.
  function down(e) {
    if (!ready || hand || input.disabled || (e.pointerType === 'mouse' && e.button !== 0)) return;
    hand = { pid: e.pointerId, touch: e.pointerType === 'touch', moved: false, from: input.value };
    fanEl.setPointerCapture?.(e.pointerId);
    root.classList.add('kq-grabbing', 'kq-pointer');     // focus for the keys, without a keyboard focus ring
    input.focus({ preventScroll: true });
    if (!hand.touch) { handTo(e); e.preventDefault(); }
  }
  function move(e) {
    if (!hand || e.pointerId !== hand.pid) return;
    hand.moved = true;
    handTo(e);
  }
  function up(e) {
    if (!hand || e.pointerId !== hand.pid) return;
    const h = hand;
    if (e.type === 'pointerup' && h.touch && !h.moved) handTo(e);           // a tap
    hand = null;
    root.classList.remove('kq-grabbing');
    if (e.type === 'pointercancel' && h.touch && input.value !== h.from) setValue(h.from);
    guardTarget = guardFor(openness());            // settle on the stepped value
    if (input.value !== h.from) input.dispatchEvent(new Event('change', { bubbles: true }));
    wake();
  }

  // ---- start -----------------------------------------------------------------------------------------------------
  on(input, 'input', fromInput);
  on(input, 'keydown', () => root.classList.remove('kq-pointer'));
  on(input, 'blur', () => root.classList.remove('kq-pointer'));
  say();
  const jsonURL = o.src || new URL('fan.json', img.currentSrc || img.src).href;
  (async () => {
    try {
      const g = await (await fetch(jsonURL)).json();
      const atlas = await loadImage(new URL('sticks.webp', jsonURL).href);
      if (!alive) return;
      G = Object.assign(g, { atlas });
      N = G.sticks.length;
      a = G.sticks.map((s) => s.a * D2R);
      gap = a.map((v, k) => (k ? v - a[k - 1] : 0));
      phi = a.slice(); om = a.map(() => 0);
      guardTarget = guardFor(openness());
      settle();                                    // land on the value at once
      canvas = document.createElement('canvas');
      canvas.className = 'kq-canvas';
      canvas.setAttribute('aria-hidden', 'true');
      fanEl.appendChild(canvas); added.push(canvas);
      ctx = canvas.getContext('2d');
      ready = true;
      layout();
      const ro = new ResizeObserver(() => layout());
      ro.observe(fanEl); offs.push(() => ro.disconnect());
      const io = new IntersectionObserver((es) => { visible = es[0].isIntersecting; if (visible) wake(); });
      io.observe(root); offs.push(() => io.disconnect());
      on(document, 'visibilitychange', () => wake());
      on(calm, 'change', () => wake());
      on(fanEl, 'pointerdown', down);
      on(fanEl, 'pointermove', move);
      on(fanEl, 'pointerup', up);
      on(fanEl, 'pointercancel', up);
      root.classList.add('kq-ready');
      draw();
    } catch (err) {
      console.warn('kongque: the fan will stay as photographed', err);
    }
  })();

  function destroy() {
    alive = false;
    cancelAnimationFrame(raf);
    offs.forEach((fn) => fn());
    added.forEach((n) => n.remove());
    root.classList.remove('kq-on', 'kq-ready', 'kq-moving', 'kq-grabbing', 'kq-pointer');
    live.delete(root);
  }
  Object.defineProperties(destroy, {
    value: { get: () => num(input.value, 0), set: (v) => setValue(v) },
    open: { get: () => (ready ? (phi[N - 1] - a[0]) / (a[N - 1] - a[0]) : openness()) },
  });
  destroy.hold = (h) => { held = !!h; if (held) { cancelAnimationFrame(raf); raf = 0; } else wake(); };
  destroy.advance = (s) => { for (let k = 0, n = Math.round(s * 240); k < n; k++) step(1 / 240); settled(); draw(); };
  destroy.settle = () => { settle(); draw(); };
  live.set(root, destroy);
  return destroy;
}

const start = () => document.querySelectorAll('[data-kongque]').forEach((el) => kongque(el));
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
else start();

/*
 *  TILT // one shared, smoothed read of how the phone is being held.
 *
 *  tilt.x / tilt.y run -1..1 (right / toward you). They are relative to how the
 *  phone was first held and the baseline drifts back slowly, so a phone resting
 *  at 50 degrees reads as level, and the effect is about *changing* the angle.
 *  Screen rotation is accounted for. Smoothed, so a shaky hand is a calm one.
 *
 *  iOS only hands over orientation after a tap, so the first touch asks. On
 *  desktop, or if permission is refused, tilt.active stays false and each piece
 *  falls back to its own pointer or drift behaviour.
 *
 *  Pages import this by the same URL so there is exactly one instance.
 */
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

const tilt = { x: 0, y: 0, active: false, listeners: new Set() };
let base = null;
let rx = 0;
let ry = 0;
let started = false;
let lastT = 0;

function read(ev) {
    if (ev.beta == null || ev.gamma == null) return;
    const ang = (screen.orientation && screen.orientation.angle) || window.orientation || 0;
    const b = ev.beta;
    const g = ev.gamma;
    let x;
    let y;
    switch (((ang % 360) + 360) % 360) {
        case 90:  x = b;  y = -g; break;
        case 180: x = -g; y = -b; break;
        case 270: x = -b; y = g;  break;
        default:  x = g;  y = b;
    }
    const now = performance.now();
    const dt = lastT ? Math.min(0.2, (now - lastT) / 1000) : 0.016;
    lastT = now;
    if (!base) base = { x, y };
    // the baseline eases toward wherever the phone is now (about 12s to settle)
    const k = 1 - Math.exp(-dt / 12);
    base.x += (x - base.x) * k;
    base.y += (y - base.y) * k;
    rx = clamp((x - base.x) / 24, -1, 1);
    ry = clamp((y - base.y) / 24, -1, 1);
    // low-pass
    const s = 1 - Math.exp(-dt / 0.09);
    tilt.x += (rx - tilt.x) * s;
    tilt.y += (ry - tilt.y) * s;
    if (!tilt.active) {
        tilt.active = true;
        tilt.listeners.forEach((fn) => fn(tilt));
    }
}

function listen() {
    if (started) return;
    started = true;
    addEventListener('deviceorientation', read, { passive: true });
}

if (typeof DeviceOrientationEvent !== 'undefined') {
    // Listening costs nothing and works wherever no permission is needed
    // (Android, and Chrome which grants it quietly). iOS stays silent until the
    // user taps, so also ask on the first touch.
    listen();
    if (typeof DeviceOrientationEvent.requestPermission === 'function') {
        addEventListener('touchend', () => {
            DeviceOrientationEvent.requestPermission()
                .then((st) => { if (st === 'granted') listen(); })
                .catch(() => {});
        }, { once: true, passive: true });
    }
}

// Desktop browsers fire one null event; only a real sensor flips .active.
export default tilt;

/* ─── kongque — Kunstnerviften, a brisé fan with a peacock (Kristiania, 1898) as a range input ───────────────
   The fan is an <img>: the Nasjonalmuseet's photograph, cut off its linen. While it is turned, a canvas over it draws the
   eighteen photographed sticks turned about the pin; fully open and at rest, what you see is the <img>.
   The control is a real <input type="range">, with its <label> and an <output>. Prefix: .kq- */

.kq {
  position: relative;
  display: grid;
  gap: var(--kq-gap, 14px);
  justify-items: center;
  color: var(--ink, #141312);
  font-family: var(--serif, 'Cormorant Garamond', Georgia, serif);
}

/* the fan's box: the photograph (2599 × 1406) plus what the closed fan reaches past it (8 px left, 16 px below) */
.kq-fan {
  position: relative;
  width: var(--kq-width, min(100%, 640px));
  aspect-ratio: 2603 / 1422;
  line-height: 0;
  -webkit-tap-highlight-color: transparent;
}
.kq-img {
  position: absolute;
  top: 0;
  left: 0.3073%;          /* 8 / 2603 */
  width: 99.8463%;       /* 2599 / 2603 */
  height: auto;
  /* painted wood lying on the page: a tight contact shadow and a soft one along its outline */
  filter: var(--kq-shadow, drop-shadow(0 .5px .8px rgba(40, 26, 10, .28)) drop-shadow(0 6px 14px rgba(40, 26, 10, .14)));
}
.kq-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: none;
  pointer-events: none;
  filter: var(--kq-shadow, drop-shadow(0 .5px .8px rgba(40, 26, 10, .28)) drop-shadow(0 6px 14px rgba(40, 26, 10, .14)));
}
.kq-moving .kq-canvas { display: block; }
.kq-moving .kq-img { visibility: hidden; }

/* handled: the fan is the slider's thumb and track. Vertical swipes still scroll the page; a sideways drag or a
   tap sets the value */
.kq-ready .kq-fan { cursor: grab; touch-action: pan-y; user-select: none; -webkit-user-select: none; }
.kq-grabbing .kq-fan { cursor: grabbing; }
.kq:not(.kq-pointer):has(.kq-input:focus-visible) .kq-fan {
  outline: 2px solid var(--accent, #c96f4a);
  outline-offset: 6px;
  border-radius: 6px;
}

/* the words: label and output on one line */
.kq-face {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: .9em;
}
.kq-label {
  font: 500 11px/1.2 var(--sans, Inter, system-ui, sans-serif);
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--ink-3, #8a857d);
}
.kq-out {
  font-family: var(--serif, 'Cormorant Garamond', Georgia, serif);
  font-size: var(--kq-size, 26px);
  line-height: 1;
  font-variant-numeric: lining-nums tabular-nums;
  color: var(--ink, #141312);
  min-width: 3ch;
}

/* the input: a native slider until the script is ready; then the fan is its picture and the input stays in the
   accessibility tree (focusable, the keys work) but out of sight */
.kq-input { width: var(--kq-width, min(100%, 640px)); accent-color: var(--accent, #c96f4a); }
.kq-ready .kq-input {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* compact: a small fan in a row (about 44 px tall), its words beside it */
.kq-compact {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  --kq-width: calc(var(--kq-height, 44px) * 2603 / 1422);
  --kq-size: 17px;
  --kq-shadow: drop-shadow(0 .5px .6px rgba(40, 26, 10, .3));
}
.kq-compact .kq-fan { flex: none; }
.kq-compact .kq-face { gap: .6em; }
.kq-compact .kq-input { width: 120px; }
.kq-compact.kq-ready .kq-input { width: 1px; }

@media (forced-colors: active) {
  .kq-moving .kq-canvas { display: none; }
  .kq-moving .kq-img { visibility: visible; }
}
